"""Build the current independent implementation report from strict reconciliation evidence."""
from pathlib import Path
import json,html
ROOT=Path(__file__).parent/'downloads/derivatives-options-futures'
D=ROOT/'reconciliation';r=json.loads((D/'results.json').read_text())
esc=html.escape
def number(x):
    return f'{x:.6f}' if isinstance(x,(int,float)) else '—'
def table(rows):
    return '<div class="table-scroll"><table><thead><tr><th>Metric / side</th><th>Original</th><th>Local</th><th>Difference</th><th>At display precision?</th></tr></thead><tbody>'+''.join('<tr><th>'+esc(x['metric']+' '+x.get('side',''))+'</th><td>'+number(x['original'])+'</td><td>'+number(x['local'])+'</td><td>'+('—' if x['difference'] is None else f"{x['difference']:+.6f}")+'</td><td>'+('Undefined locally' if x['matches_display_precision'] is None else 'Yes' if x['matches_display_precision'] else 'No')+'</td></tr>' for x in rows)+'</tbody></table></div>'
prices=''
for c in r['pricing']:
    p=c['parameters']
    prices+='<h3>'+esc(c['name'])+'</h3><p>'+esc(c['mapping_note'])+'</p><p>'+esc(f"S={p['spot']}, K={p['strike']}, days={p['days']:.8g}, r={p['rate']*100:.6g}%, IV={p['volatility']*100:.6g}%, yield={p['yield']*100:.6g}%.")+'</p>'
    for v in c['variants']:
        prices+='<details><summary>'+esc(v['model'])+(' · '+str(v['steps'])+' steps' if v['steps'] else '')+' · all prices and Greeks</summary>'+table(v['rows'])+'</details>'
prob=''
for v in r['probability']['variants']:
    prob+='<h3>'+esc(v['driftConvention'])+'</h3>'+table(v['rows'])+'<p>Local terminal sum: '+f"{v['terminalSum']:.12f}"+'. Local union residual: '+f"{v['localUnionResidual']:.3g}"+'.</p>'
features=[('Options Calculator','European BSM; American CRR; yield or dated cash schedule; call/put Greeks and IV','Cash dividends use an escrowed approximation. No original server engine or exact vendor tree convention.'),('Probability Calculator','Terminal regions, continuously monitored touch/joint events, drift-centered deviation intervals','Risk-neutral default; optional zero-log drift hypothesis. Original joint events remain different.'),('Profit & Loss Simulator','Editable stock/call/put legs, signed quantity, multiplier, IV/style/expiry, pre-expiry and expiry P&L, Greeks, time/spot/IV scenarios, JSON import/export','Single underlying. No assignment simulation, fees, financing, stock dividends or reconstructed historical settlement paths.'),('Trending / Stock / Options monitors','Imported snapshot monitor, option-volume ranking, dated prices and quotes','Ranks only imported records. No original all-market feed, unavailable fields shown as missing.'),('Historical / Implied Volatility','Price history, rolling annualized HV, option chain and imported contract IV','No proprietary IVX. One observed price gap is one interval; adjusted-close support exists in the model API, while the UI charts close.'),('Course supplements','Seven expiry strategies, parity and futures margin arithmetic','Illustrative margin, not an exchange risk/margin service.')]
feature_table='<div class="table-scroll"><table><thead><tr><th>Original function</th><th>Local implementation</th><th>Scope</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(t)+'</td>' for t in row)+'</tr>' for row in features)+'</tbody></table></div>'
a=json.loads((ROOT/'oic-original/american-validation.json').read_text());p=json.loads((ROOT/'oic-original/probability-validation.json').read_text());f=json.loads((ROOT/'oic-original/portfolio-validation.json').read_text());m=json.loads((ROOT/'validation-report.json').read_text())
body=f'''<main class="content"><div class="eyebrow">Independent implementation · 5 October 2026</div><h1>Working offline.<br>Differences measured.</h1><p class="notice">The local lab now implements American pricing, cash-dividend valuation, probabilities, editable position scenarios and imported market/HV analysis. It is not an offline copy of the OIC/iVolatility server engine. Full original numerical equivalence is not established.</p><div class="toolbar"><a href="../tools/index.html">Open working lab →</a><a href="results.json">Reconciliation JSON</a><a href="../oic-original/index.html">Original resources</a></div><h2>Coverage</h2>{feature_table}<h2>Models and verification</h2><p>The existing BSM/arithmetic suite passed {m['checks']} checks; the American suite passed {a['checks']} checks; the probability suite passed {p['checks']} checks; the portfolio/import/HV suite passed {f['testCount']} test groups. Groups and individual checks are separate units. These tests support the documented models, rather than vendor identity.</p><p>American validation uses QuantLib reference examples, exercise bounds, convergence, numerical Greeks, IV round trips and cash timing. Probability validation includes independent first-exit quadrature, a seeded Brownian-bridge Monte Carlo check, absorbing-barrier series convergence and event identities. Position tests use hand-calculated signed costs/expiry payoffs, BSM Greeks, IV-shift units, American integration, cash-event timing, strict imports and independently computed HV.</p><ul><li><a href="../validation-report.json">BSM / arithmetic evidence</a></li><li><a href="../oic-original/american-model.md">American / cash-dividend model</a> · <a href="../oic-original/american-validation.json">91-check evidence</a></li><li><a href="../oic-original/probability-methodology.md">Probability methodology</a> · <a href="../oic-original/probability-validation.json">Probability evidence</a></li><li><a href="../oic-original/portfolio-model.md">Portfolio / market / HV model</a> · <a href="../oic-original/portfolio-validation.json">16 test groups</a></li><li><a href="browser-validation.json">Browser interaction evidence</a> · <a href="live-attempts.json">Fresh online attempt record</a></li></ul><p>Local time is ACT/365 with fractional calendar days. Theta is per day; vega and rho are per one percentage point; option values are per share. Positions scale by signed quantity and multiplier. Tree Greeks may oscillate with step count. Cash at expiry is excluded, and scheduled payments are shifted by elapsed scenario time. Immediate exercise can make implied volatility non-unique.</p><h2>Original pricing reconciliation</h2><p>Three earlier European cases and one American case, plus {len(r['pricing'])-4} fresh cases, were captured from the authenticated original UI. Every original pricing/Greek value has four displayed decimals: tolerance is 0.00005, unchanged across models. The original stock input used a zero regular cash dividend; mapping that to q=0 is an assumption. The guide names a 100-step binomial American model but does not establish its exact construction or Greek bumps. Raising local CRR steps does not remove all differences; no fitted adjustment is applied. Fresh zero-rate one-year and fractional-day cases also have residual differences. The half-day case produces positive time value, so this observation does not support simple truncation of hours. Exact vendor time/discount/volatility conventions remain unknown. The fresh zero-time case returns correct intrinsic prices (5/0), while its Alpha and Rho displays are nonzero; their boundary semantics or stale-output behavior is unresolved. Local BSM boundary Greeks are explicitly undefined and are not treated as numeric matches.</p>{prices}<h3>Original inverse IV sample</h3><p>Target price 13.7343, S=100, K=95, T=0.25, r=10%, q=0. Original IV display tolerance: 0.005 percentage points.</p>{table(r['impliedVolatility'])}<h2>Probability reconciliation</h2><p>S=100, targets 90/110, 180 days 12 hours 15 minutes, volatility=20%, rate=3%, yield=2%. Terminal output tolerance is 0.5 percentage points; touching tolerance is 0.005 percentage points; deviation-price tolerance is 0.005 price units.</p><p class="notice">Zero log drift matches the three rounded terminal regions and two individual touch values in this single sample. That is evidence for an optional hypothesis, not proof of the vendor convention. Joint events and deviation prices still differ. The default model remains risk-neutral GBM.</p><p>The original marginals and Both imply Either = 88.21%, while the captured original displays 53.77%. Its Either + Neither sum is 100%, but the ordinary union identity is unresolved. We preserve this discrepancy and use internally consistent joint events locally.</p>{prob}<h2>Position and market reconciliation limits</h2><p>The captured original stock-only position has 100 shares at entry 100 and signed cost 10,000; local cost matches exactly. Its Delta label is a percentage, so this observation does not verify the local delta's units or full option valuation. No original option-leg scenario output, cash-dividend price example, market ranking, historical price series or proprietary IVX golden reference was obtained. Local examples are explicitly synthetic and importing them does not claim original data coverage.</p><h2>Evidence and reproducibility</h2><p><a href="fresh-american-preview.png">Fresh original American screenshot</a> preserves fictional test inputs. The deep ITM put has original and local immediate-exercise value 20; its original Delta/Gamma differ from local intrinsic sensitivities, so price agreement does not establish Greek agreement.</p><p><a href="../oic-original/online-reference-cases.json">Earlier original pricing inputs and outputs</a> · <a href="fresh-original-cases.json">Fresh original inputs and outputs</a> · <a href="../oic-original/probability-calculator/online-case.json">Original probability capture</a> · <a href="../oic-original/comparison.html">Earlier four-panel baseline comparison</a> · <a href="../oic-original/source-review.json">Original server-dependency source evidence</a>. The saved official PDF guides remain in the original resource archive. Re-run root scripts reconcile_models.cjs and build_reconciliation.py to regenerate this report without network or credentials.</p><p>The local pages load scripts, styles and models from this folder. CSP blocks outbound connections. Browser checks used loopback HTTP rather than physically disconnecting the computer. Keep the entire course folder together and use its launcher.</p><p><a href="../completeness-report.html">Full course completeness report</a> · <a href="../integrity-report.json">File/link checks</a> · <a href="../SHA256SUMS.txt">Package hashes</a></p></main>'''
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self' data:; script-src 'self'; style-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'"><title>Implementation & reconciliation · Derivatives lab</title><link rel="stylesheet" href="../style.css?rev=20261006-audit"><link rel="stylesheet" href="../tools/advanced.css"></head><body><div class="wrap"><header class="topbar"><a href="../index.html">← Course library</a><span class="tag">RECONCILIATION</span></header>'''
(D/'index.html').write_text(head+body+'</div></body></html>')
(D/'README.md').write_text('# Independent offline implementation and reconciliation\n\n'+html.unescape(__import__('lxml.html',fromlist=['html']).fromstring(body).text_content())+'\n')
print('Built current implementation / reconciliation report')
